.version 8.0
.target sm_89
.address_size 64
// One-block-per-batch-sample LayerNorm over last 3 dims with affine
.visible .entry layernorm_fwd(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u32 N,
    .param .u32 F,
    .param .u32 D1,
    .param .u32 D2,
    .param .f32 eps
)
{
    .reg .pred   %p<8>;
    .reg .b32    %r<40>;
    .reg .b64    %rd<40>;
    .reg .f32    %f<40>;
    // Shared memory for block reduction and stats
    .shared .align 4 .f32 sh_sum[256];
    .shared .align 4 .f32 sh_sumsq[256];
    .shared .align 4 .f32 sh_stats[2];
    // Load params
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [y_ptr];
    ld.param.u64 %rd3, [w_ptr];
    ld.param.u64 %rd4, [b_ptr];
    ld.param.u32 %r1,  [N];
    ld.param.u32 %r2,  [F];
    ld.param.u32 %r3,  [D1];
    ld.param.u32 %r4,  [D2];
    ld.param.f32 %f1,  [eps];
    // Convert to global address space
    cvta.to.global.u64 %rd10, %rd1; // x
    cvta.to.global.u64 %rd11, %rd2; // y
    cvta.to.global.u64 %rd12, %rd3; // w (gamma)
    cvta.to.global.u64 %rd13, %rd4; // b (beta)
    // Thread/block info
    mov.u32 %r10, %tid.x;
    mov.u32 %r11, %ntid.x;
    mov.u32 %r12, %ctaid.x;
    // Compute M = F * D1 * D2
    mul.lo.u32 %r20, %r2, %r3;
    mul.lo.u32 %r20, %r20, %r4; // M
    // OOB block check: if blockIdx.x >= N return
    setp.ge.u32 %p1, %r12, %r1;
    @%p1 bra DONE;
    // Base index for this sample: base = blockIdx.x * M
    mul.lo.u32 %r21, %r12, %r20; // base (elements)
    // Initialize local accumulators
    mov.f32 %f10, 0f00000000; // local sum
    mov.f32 %f11, 0f00000000; // local sumsq
    // Vectorized accumulation: process 4 elements per iteration
    // M4 = M & ~3, idx4 = tid*4, stride4 = blockDim.x*4
    and.b32 %r26, %r20, 0xFFFFFFFC;
    shl.b32 %r22, %r10, 2;
    shl.b32 %r27, %r11, 2;
SUM_LOOP_V4:
    setp.ge.u32 %p2, %r22, %r26;
    @%p2 bra SUM_LOOP_V4_END;
    // off_ele = base + idx4
    add.u32 %r23, %r21, %r22;
    // byte offset
    mul.wide.u32 %rd20, %r23, 4;
    add.u64 %rd21, %rd10, %rd20; // &x[base+idx4]
    ld.global.v4.f32 {%f24,%f25,%f26,%f27}, [%rd21];
    // accumulate v4
    fma.rn.f32 %f11, %f24, %f24, %f11;
    fma.rn.f32 %f11, %f25, %f25, %f11;
    fma.rn.f32 %f11, %f26, %f26, %f11;
    fma.rn.f32 %f11, %f27, %f27, %f11;
    add.f32 %f10, %f10, %f24;
    add.f32 %f10, %f10, %f25;
    add.f32 %f10, %f10, %f26;
    add.f32 %f10, %f10, %f27;
    // idx4 += stride4
    add.u32 %r22, %r22, %r27;
    bra SUM_LOOP_V4;
SUM_LOOP_V4_END:
    // Scalar tail for remaining elements
    add.u32 %r22, %r26, %r10; // idx = M4 + tid
TAIL_SUM_LOOP:
    setp.ge.u32 %p7, %r22, %r20;
    @%p7 bra SUM_LOOP_END;
    // off_ele = base + idx
    add.u32 %r23, %r21, %r22;
    // byte offset
    mul.wide.u32 %rd20, %r23, 4;
    add.u64 %rd21, %rd10, %rd20; // &x[base+idx]
    ld.global.f32 %f12, [%rd21];
    // accumulate
    fma.rn.f32 %f11, %f12, %f12, %f11; // sumsq += v*v
    add.f32 %f10, %f10, %f12;          // sum   += v
    // idx += blockDim.x
    add.u32 %r22, %r22, %r11;
    bra TAIL_SUM_LOOP;
SUM_LOOP_END:
    // Write locals to shared
    mov.u64 %rd30, sh_sum;
    mov.u64 %rd31, sh_sumsq;
    mov.u64 %rd32, sh_stats;
    mul.wide.u32 %rd22, %r10, 4;
    add.u64 %rd23, %rd30, %rd22;
    add.u64 %rd24, %rd31, %rd22;
    st.shared.f32 [%rd23], %f10;
    st.shared.f32 [%rd24], %f11;
    bar.sync 0;
    // Block reduction
    mov.u32 %r30, %r11;         // r30 = ntid
    shr.u32 %r30, %r30, 1;      // stride = ntid >> 1
RED_LOOP:
    setp.eq.u32 %p3, %r30, 0;
    @%p3 bra RED_DONE;
    setp.lt.u32 %p4, %r10, %r30;
    @!%p4 bra RED_SKIP;
    // idx1 = tid, idx2 = tid + stride
    // addresses
    mul.wide.u32 %rd25, %r10, 4;        // tid*4
    add.u64 %rd26, %rd30, %rd25;        // &sh_sum[tid]
    add.u64 %rd27, %rd31, %rd25;        // &sh_sumsq[tid]
    add.u32 %r31, %r10, %r30;           // tid + stride
    mul.wide.u32 %rd28, %r31, 4;        // (tid+stride)*4
    add.u64 %rd29, %rd30, %rd28;        // &sh_sum[tid+stride]
    add.u64 %rd33, %rd31, %rd28;        // &sh_sumsq[tid+stride]
    ld.shared.f32 %f20, [%rd26];
    ld.shared.f32 %f21, [%rd29];
    add.f32 %f20, %f20, %f21;
    st.shared.f32 [%rd26], %f20;
    ld.shared.f32 %f22, [%rd27];
    ld.shared.f32 %f23, [%rd33];
    add.f32 %f22, %f22, %f23;
    st.shared.f32 [%rd27], %f22;
RED_SKIP:
    bar.sync 0;
    shr.u32 %r30, %r30, 1;
    bra RED_LOOP;
RED_DONE:
    // Compute mean/var and inv_std at tid 0
    setp.ne.u32 %p5, %r10, 0;
    @%p5 bra STATS_DONE;
    // load sums
    ld.shared.f32 %f30, [sh_sum];
    ld.shared.f32 %f31, [sh_sumsq];
    // mean = sum / M
    cvt.rn.f32.u32 %f32, %r20;
    div.rn.f32 %f33, %f30, %f32; // mean
    // msq = sumsq / M
    div.rn.f32 %f34, %f31, %f32; // mean of squares
    // var = msq - mean*mean
    mul.f32 %f35, %f33, %f33;
    sub.f32 %f36, %f34, %f35;    // var
    // inv_std = 1.0 / sqrt(var + eps)
    add.f32 %f37, %f36, %f1;
    sqrt.rn.f32 %f38, %f37;
    mov.f32 %f39, 1.0;
    div.rn.f32 %f18, %f39, %f38; // inv_std
    // store mean and inv_std
    st.shared.f32 [sh_stats], %f33;          // mean
    st.shared.f32 [sh_stats+4], %f18;        // inv_std
STATS_DONE:
    bar.sync 0;
    // Load stats to all threads
    ld.shared.f32 %f13, [sh_stats];      // mean
    ld.shared.f32 %f14, [sh_stats+4];    // inv_std
    // Second pass: write normalized output with affine (vectorized + tail)
    // idx4 = tid*4, stride4 = blockDim.x*4 (reuse r26=M4)
    shl.b32 %r24, %r10, 2; // idx4
    shl.b32 %r27, %r11, 2; // stride4
NORM_LOOP_V4:
    setp.ge.u32 %p6, %r24, %r26;
    @%p6 bra NORM_SCALAR_TAIL;
    // element offsets
    add.u32 %r25, %r21, %r24;               // base + idx4
    mul.wide.u32 %rd34, %r25, 4;
    mul.wide.u32 %rd35, %r24, 4;
    // x[base+idx4 .. +3]
    add.u64 %rd36, %rd10, %rd34;
    ld.global.v4.f32 {%f15,%f16,%f17,%f18}, [%rd36];
    // w[idx4..+3], b[idx4..+3]
    add.u64 %rd37, %rd12, %rd35;
    add.u64 %rd38, %rd13, %rd35;
    ld.global.v4.f32 {%f19,%f20,%f21,%f22}, [%rd37]; // gamma
    ld.global.v4.f32 {%f23,%f24,%f25,%f26}, [%rd38]; // beta
    // y = ((x - mean) * inv_std) * gamma + beta (in-place on x regs)
    sub.f32 %f15, %f15, %f13;
    mul.f32 %f15, %f15, %f14;
    mul.f32 %f15, %f15, %f19;
    add.f32 %f15, %f15, %f23;
    sub.f32 %f16, %f16, %f13;
    mul.f32 %f16, %f16, %f14;
    mul.f32 %f16, %f16, %f20;
    add.f32 %f16, %f16, %f24;
    sub.f32 %f17, %f17, %f13;
    mul.f32 %f17, %f17, %f14;
    mul.f32 %f17, %f17, %f21;
    add.f32 %f17, %f17, %f25;
    sub.f32 %f18, %f18, %f13;
    mul.f32 %f18, %f18, %f14;
    mul.f32 %f18, %f18, %f22;
    add.f32 %f18, %f18, %f26;
    // store y4
    add.u64 %rd39, %rd11, %rd34;
    st.global.v4.f32 [%rd39], {%f15,%f16,%f17,%f18};
    // idx4 += stride4
    add.u32 %r24, %r24, %r27;
    bra NORM_LOOP_V4;
NORM_SCALAR_TAIL:
    // scalar tail pass: idx = M4 + tid
    add.u32 %r24, %r26, %r10;
NORM_LOOP:
    setp.ge.u32 %p6, %r24, %r20;
    @%p6 bra NORM_DONE;
    // element offsets
    add.u32 %r25, %r21, %r24;               // base + idx
    mul.wide.u32 %rd34, %r25, 4;
    mul.wide.u32 %rd35, %r24, 4;
    // x[base+idx]
    add.u64 %rd36, %rd10, %rd34;
    ld.global.f32 %f15, [%rd36];
    // w[idx], b[idx]
    add.u64 %rd37, %rd12, %rd35;
    add.u64 %rd38, %rd13, %rd35;
    ld.global.f32 %f16, [%rd37]; // gamma
    ld.global.f32 %f17, [%rd38]; // beta
    // y = ((x - mean) * inv_std) * gamma + beta
    sub.f32 %f19, %f15, %f13;
    mul.f32 %f19, %f19, %f14;
    mul.f32 %f19, %f19, %f16;
    add.f32 %f19, %f19, %f17;
    // store y
    add.u64 %rd39, %rd11, %rd34;
    st.global.f32 [%rd39], %f19;
    // idx += blockDim.x
    add.u32 %r24, %r24, %r11;
    bra NORM_LOOP;
NORM_DONE:
DONE:
    ret;
