_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("layernorm_fwd")

class ModelNew(nn.Module):
    """
    Simple model that performs Layer Normalization.
    """
    def __init__(self, normalized_shape: tuple):
        """
        Initializes the LayerNorm-equivalent parameters.

        Args:
            normalized_shape (tuple): Shape of the input tensor to be normalized.
        """
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        # Match PyTorch LayerNorm default parameter initialization
        self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float32))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies Layer Normalization to the input tensor across the last len(normalized_shape) dims.
        """
        assert x.dtype == torch.float32, "This implementation supports float32 inputs only."
        # Expect x shape: (N, *normalized_shape)
        N = x.shape[0]
        # normalized across last 3 dims, as per reference usage
        F = x.shape[-3]
        D1 = x.shape[-2]
        D2 = x.shape[-1]

        # Output allocation
        y = torch.empty_like(x)

        # Launch PTX kernel
        module = _get_ptx_module()
        module.launch(
            "layernorm_fwd",
            grid=(int(N), 1, 1),
            block=(256, 1, 1),
            arguments=[x, y, self.weight, self.bias, u32(int(N)), u32(int(F)), u32(int(D1)), u32(int(D2)), f32(float(self.eps))],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
